<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Generative AI Competitive Landscape — Q1 2026</title>
<style>
  :root {{
    --primary: #1e293b;
    --accent: #2563eb;
    --accent-light: #dbeafe;
    --bg: #ffffff;
    --surface: #f8fafc;
    --border: #e2e8f0;
    --text: #1e293b;
    --text-secondary: #64748b;
    --red: #ef4444;
    --amber: #f59e0b;
    --green: #22c55e;
    --purple: #8b5cf6;
  }}
  * {{ margin:0; padding:0; box-sizing:border-box; }}
  body {{ font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Inter, Roboto, sans-serif;
         color: var(--text); background: var(--bg); line-height: 1.6; }}
  .container {{ max-width: 1100px; margin: 0 auto; padding: 40px 32px; }}

  /* Header */
  .report-header {{ border-bottom: 3px solid var(--accent); padding-bottom: 24px; margin-bottom: 40px; }}
