  .report-footer {{ border-top: 1px solid var(--border); padding-top: 16px; margin-top: 48px;
                    font-size: 12px; color: var(--text-secondary); text-align: center; }}

  .takeaway-list {{ list-style: none; padding: 0; }}
  .takeaway-list li {{ padding: 10px 16px; margin-bottom: 8px; background: var(--surface);
